head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};

scwin.onpageload = function() {
	scwin.tabIndex = 1;
};

scwin.addTab = function(label, tabId, src) {
	var tabOpt = {
		label: label,
		closable: true
	};
	var contOpt = {
		frameMode: "wframe",
		scope: true,
		src: src,
		alwaysDraw: false,
		title: tabId,
		processMsgFrame: scwin.tabIndex % 2 === 1
	};
	tac_main.addTab(tabId, tabOpt, contOpt);
};

scwin.btn_trigger1_onclick = function(e) {
	var tabId = "sub" + scwin.tabIndex;
	var label = scwin.tabIndex % 2 === 1 ? "내부" : "외부";
	var src = "/sample/common_link/Submission_processMsg_tabControl_wframe_WEFF-543_(WSQ-3971)_sub.xml";
	scwin.addTab(label, tabId, src);
	scwin.tabIndex++;
};

scwin.__isCheck = function() {
	return scwin.__getDom($p.id + 'tac_main_contents_sub1_body_' + $p.id + 'tac_main_contents_sub1_body_wq_processMsgComp') != null;
};
